const messaging = firebase.messaging();

// Fires for push messages that arrive while no Study2Gate tab has focus
// (backgrounded tab, or the site closed entirely). Foreground delivery
// while a tab IS focused is handled instead by onMessage() in
// src/firebase/messaging.js, which deliberately does not show a native
// notification (see that file for why).
messaging.onBackgroundMessage((payload) => {
  const title = payload.notification?.title || payload.data?.title || "Study2Gate";
  const body = payload.notification?.body || payload.data?.body || "";
  const url = payload.data?.url || "/";

  self.registration.showNotification(title, {
    body,
    icon: "/study2gate-notification-icon.png",
    badge: "/study2gate-notification-icon.png",
    data: { url },
    tag: payload.data?.notificationId || undefined,
  });
});

// Clicking the notification focuses an already-open Study2Gate tab and
// navigates it to the relevant page, instead of always opening a new tab.
self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetUrl = event.notification.data?.url || "/";

  event.waitUntil(
    (async () => {
      const clientsList = await clients.matchAll({ type: "window", includeUncontrolled: true });
      const origin = self.location.origin;

      for (const client of clientsList) {
        if (client.url.startsWith(origin)) {
          await client.focus();
          if ("navigate" in client) {
            try {
              await client.navigate(targetUrl);
            } catch {
              // Some browsers restrict cross-origin-looking navigate calls
              // even for same-origin URLs from a SW context; postMessage
              // lets the already-loaded app route client-side instead.
              client.postMessage({ type: "push-notification-click", url: targetUrl });
            }
          }
          return;
        }
      }

      await clients.openWindow(origin + targetUrl);
    })()
  );
});

// --- PWA caching (offline support + install eligibility) ---------------
//
// Hand-rolled rather than Workbox: CRA build output has content-hashed
// filenames we can't enumerate here (this script runs in "prebuild",
// before webpack emits those files), so there's nothing meaningful to
// precache by URL. Instead this caches same-origin static assets the
// first time they're actually requested, and treats navigations
// (page loads/refreshes) as network-first so users always get a fresh
// app shell when online, falling back to the cached shell when offline.
//
// Deliberately NOT cached: requests to the API/backend origin, or
// anything under /api — those must always hit the network so auth state
// and live data are never served stale from cache.

const CACHE_NAME = "study2gate-shell-v2";
const APP_SHELL_URL = "/";

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      try {
        await cache.add(APP_SHELL_URL);
      } catch {
        // Best-effort — an offline/unavailable network during install
        // shouldn't block activation.
      }
      self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name !== CACHE_NAME).map((name) => caches.delete(name))
      );
      await self.clients.claim();
    })()
  );
});

const isApiRequest = (url) =>
  url.pathname.startsWith("/api") || url.pathname.startsWith("/socket.io") || url.origin !== self.location.origin;

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (isApiRequest(url)) return; // let API/socket calls hit the network untouched

  // Navigations (loading/refreshing a page): try the network first so
  // the app shell stays fresh, fall back to the cached shell offline.
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const response = await fetch(request);
          const cache = await caches.open(CACHE_NAME);
          cache.put(APP_SHELL_URL, response.clone());
          return response;
        } catch {
          const cache = await caches.open(CACHE_NAME);
          const cached = await cache.match(APP_SHELL_URL);
          return cached || Response.error();
        }
      })()
    );
    return;
  }

  // Static assets (hashed JS/CSS bundles, images, fonts): cache-first,
  // refreshing the cache in the background on each hit.
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      const cached = await cache.match(request);
      const networkFetch = fetch(request)
        .then((response) => {
          if (response.ok) cache.put(request, response.clone());
          return response;
        })
        .catch(() => null);
      return cached || (await networkFetch) || Response.error();
    })()
  );
});
